const DS_CSS = "/* ============================================================\n   For Claire · 设计系统\n   字体：Manrope（拉丁）+ 系统中文字体\n   排版：Tailwind 字阶 / 命名文字样式\n   间距：8 基准 token\n   动效：cubic-bezier(0.22,1,0.36,1)\n   ============================================================ */\n\n@font-face {\n  font-family: \"Manrope\";\n  src: url(\"/fonts/manrope-latin.woff2\") format(\"woff2\");\n  font-weight: 400 700;\n  font-style: normal;\n  font-display: swap;\n}\n\n:root {\n  /* —— 字体 —— */\n  --font: \"Manrope\", -apple-system, BlinkMacSystemFont, \"PingFang SC\",\n          \"Hiragino Sans GB\", \"Microsoft YaHei\", \"Source Han Sans SC\", sans-serif;\n\n  /* —— 颜色 —— */\n  --bg: #f5f9f6;\n  --bg-soft: #edf5f0;\n  --panel: #ffffff;\n  --ink: #1f2a23;\n  --ink-2: #374151;\n  --muted: #6b7a70;\n  --faint: #9aa79f;\n  --line: #e3ebe5;\n  --line-strong: #cfdcd4;\n  --brand: #16a34a;\n  --brand-dark: #15803d;\n  --brand-soft: #e9f7ee;\n  --brand-soft-2: #dcf5e5;\n\n  /* —— 间距（8 基准）—— */\n  --s-25: 2px;\n  --s-50: 4px;\n  --s-75: 8px;\n  --s-100: 12px;\n  --s-200: 16px;\n  --s-300: 24px;\n  --s-400: 32px;\n  --s-500: 40px;\n  --s-600: 48px;\n  --s-700: 64px;\n  --s-800: 80px;\n  --s-900: 96px;\n\n  /* —— 圆角（Tailwind）—— */\n  --r-sm: 2px;\n  --r: 4px;\n  --r-md: 6px;\n  --r-lg: 8px;\n  --r-xl: 12px;\n  --r-2xl: 16px;\n  --r-3xl: 24px;\n  --r-full: 999px;\n\n  /* —— 动效 —— */\n  --ease: cubic-bezier(0.22, 1, 0.36, 1);\n  --dur-fast: 200ms;\n  --dur: 300ms;\n  --dur-slow: 500ms;\n\n  /* —— 层级与阴影 —— */\n  --shadow-1: 0 1px 2px rgba(16, 24, 40, .04);\n  --shadow-2: 0 1px 2px rgba(16, 24, 40, .05), 0 8px 24px rgba(16, 24, 40, .06);\n  --shadow-3: 0 12px 32px rgba(16, 24, 40, .12);\n}\n\n/* ============================================================\n   基础\n   ============================================================ */\n\n*, *::before, *::after { box-sizing: border-box; }\n\nhtml { -webkit-text-size-adjust: 100%; }\n\nbody {\n  font-family: var(--font);\n  font-feature-settings: \"tnum\" 1;\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n  text-rendering: optimizeLegibility;\n}\n\n/* 无斜体（logo 除外，由品牌字样式单独指定） */\nbody, input, textarea, select, button { font-style: normal; }\n\nbutton, input, textarea, select { font-family: inherit; }\n\n/* 焦点环 —— 键盘可见 */\n:focus-visible {\n  outline: 2px solid var(--brand);\n  outline-offset: 2px;\n  border-radius: var(--r);\n}\n\n/* 选中态 */\n::selection { background: var(--brand-soft-2); color: var(--ink); }\n\n/* 滚动条（WebKit） */\n::-webkit-scrollbar { width: 10px; height: 10px; }\n::-webkit-scrollbar-track { background: transparent; }\n::-webkit-scrollbar-thumb {\n  background: var(--line-strong);\n  border-radius: var(--r-full);\n  border: 3px solid transparent;\n  background-clip: content-box;\n}\n::-webkit-scrollbar-thumb:hover { background: #b9c9c0; background-clip: content-box; }\n\n/* 减少动效 */\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after {\n    animation-duration: .01ms !important;\n    animation-iteration-count: 1 !important;\n    transition-duration: .01ms !important;\n    scroll-behavior: auto !important;\n  }\n}\n\n/* ============================================================\n   文字样式（命名，直接用 class）\n   ============================================================ */\n\n.heading-1 { font-size: 60px; line-height: 1;    font-weight: 600; letter-spacing: -.02em; text-wrap: balance; }\n.heading-2 { font-size: 48px; line-height: 1;    font-weight: 600; letter-spacing: -.02em; text-wrap: balance; }\n.heading-3 { font-size: 36px; line-height: 40px; font-weight: 600; letter-spacing: -.01em; text-wrap: balance; }\n.heading-4 { font-size: 30px; line-height: 36px; font-weight: 600; letter-spacing: -.01em; text-wrap: balance; }\n.heading-5 { font-size: 24px; line-height: 32px; font-weight: 600; text-wrap: balance; }\n.heading-6 { font-size: 20px; line-height: 28px; font-weight: 600; }\n\n.title-1 { font-size: 20px; line-height: 28px; font-weight: 500; }\n.title-2 { font-size: 18px; line-height: 28px; font-weight: 500; }\n.title-3 { font-size: 16px; line-height: 24px; font-weight: 500; }\n.title-4 { font-size: 14px; line-height: 20px; font-weight: 500; }\n.title-5 { font-size: 12px; line-height: 16px; font-weight: 500; }\n\n.body-1 { font-size: 16px; line-height: 24px; font-weight: 600; }\n.body-2 { font-size: 16px; line-height: 24px; font-weight: 500; }\n.body-3 { font-size: 16px; line-height: 24px; font-weight: 400; }\n.body-4 { font-size: 14px; line-height: 20px; font-weight: 600; }\n.body-5 { font-size: 14px; line-height: 20px; font-weight: 500; }\n.body-6 { font-size: 14px; line-height: 20px; font-weight: 400; }\n\n.button-lg  { font-size: 18px; line-height: 28px; font-weight: 600; }\n.button-md  { font-size: 16px; line-height: 24px; font-weight: 600; }\n.button-sm  { font-size: 14px; line-height: 20px; font-weight: 600; }\n.button-xsm { font-size: 12px; line-height: 16px; font-weight: 600; }\n\n.caption-1 { font-size: 14px; line-height: 20px; font-weight: 500; }\n.caption-2 { font-size: 14px; line-height: 20px; font-weight: 400; }\n.caption-3 { font-size: 12px; line-height: 16px; font-weight: 600; }\n.caption-4 { font-size: 12px; line-height: 16px; font-weight: 500; }\n.caption-5 { font-size: 12px; line-height: 16px; font-weight: 400; }\n\n/* 正文防孤行 */\np, li { text-wrap: pretty; }\n\n/* ============================================================\n   通用组件\n   ============================================================ */\n\n/* 跳转到主内容（键盘可达性） */\n.skip-link {\n  position: absolute;\n  left: -9999px;\n  top: 0;\n  z-index: 999;\n  padding: var(--s-75) var(--s-200);\n  background: var(--brand);\n  color: #fff;\n  border-radius: 0 0 var(--r-lg) 0;\n  text-decoration: none;\n}\n.skip-link:focus { left: 0; }\n\n/* 返回 / 次要按钮 */\n.btn-secondary {\n  display: inline-flex;\n  align-items: center;\n  gap: var(--s-75);\n  padding: var(--s-75) var(--s-100);\n  border: 1px solid var(--line);\n  border-radius: var(--r-lg);\n  background: var(--panel);\n  color: var(--brand-dark);\n  text-decoration: none;\n  cursor: pointer;\n  transition: border-color var(--dur) var(--ease),\n              background-color var(--dur) var(--ease),\n              transform var(--dur) var(--ease);\n}\n.btn-secondary:hover { border-color: var(--brand); background: var(--brand-soft); }\n.btn-secondary:active { transform: translateY(1px); }\n\n/* 主按钮 */\n.btn-primary {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: var(--s-75);\n  padding: var(--s-75) var(--s-100);\n  border: none;\n  border-radius: var(--r-lg);\n  background: var(--brand);\n  color: #fff;\n  text-decoration: none;\n  cursor: pointer;\n  transition: background-color var(--dur) var(--ease),\n              transform var(--dur) var(--ease),\n              box-shadow var(--dur) var(--ease);\n}\n.btn-primary:hover { background: var(--brand-dark); box-shadow: 0 6px 18px rgba(22, 163, 74, .22); }\n.btn-primary:active { transform: translateY(1px); }\n.btn-primary:disabled { background: #c3cdc6; cursor: not-allowed; box-shadow: none; }\n\n/* 输入框 */\n.field-input {\n  width: 100%;\n  padding: var(--s-100);\n  border: 1px solid var(--line);\n  border-radius: var(--r-xl);\n  background: var(--bg-soft);\n  color: var(--ink);\n  transition: border-color var(--dur) var(--ease),\n              background-color var(--dur) var(--ease),\n              box-shadow var(--dur) var(--ease);\n}\n.field-input::placeholder { color: var(--faint); }\n.field-input:focus {\n  outline: none;\n  border-color: var(--brand);\n  background: var(--panel);\n  box-shadow: 0 0 0 3px rgba(22, 163, 74, .12);\n}\n\n/* 卡片 */\n.card-flat {\n  background: var(--panel);\n  border: 1px solid var(--line);\n  border-radius: var(--r-2xl);\n  box-shadow: var(--shadow-1);\n}\n";

