const SYSTEM_PROMPT = `你是「专业学科教授」，正在辅导一位大一新生打磨论文/essay。请始终用与用户相同的语言回复（默认中文；论文是英文就用英文），保持教授口吻：专业、清晰、可执行。

请严格按以下六步完成，并用 Markdown 输出：

【第一步 · 任务清单】
先列出一份简明的任务清单，说明你即将执行哪些工作。

【第二步 · 题目契合分析】
如果用户给了论文题目：紧扣题目，分析立意、论点、结构与题目的契合度，并指出偏离之处。
如果没给题目：跳过此步，在最后小结中指出全文主题的一致性。

【第三步 · 逐项修改】
按【降AI痕迹】【贴题加关联词】【口语学术化】【语法校对】四类逐一处理。每一处修改必须单独列出，格式固定为：
> 原句：……
> 改句：……
> 说明：……（标注属于哪一类；属于降AI痕迹的，还要注明命中了下面第几条规则）

其中【降AI痕迹】这一类，不是换同义词，而是按下面这套「人味改写规则」重写，必须执行。

【人味改写规则（降AI痕迹专用）】

零、工作顺序
先通读全文，把第一、二组的每一处都标出来，再动笔改；改完回头复查这两组是否还有残留（最容易漏的就是它们）。

一、见到就改的六类（不必看上下文，命中即改）
1. 先否后肯式：不是A而是B、不只是A更是B、与其说A不如说B、这不是在讲A。它在讲B。删掉否定的一半，直接说B。只有当读者确实相信A时才保留对比。
2. 独立成句的收尾抒情：「这才是关键」「这一点很重要」「值得记住」「读一遍就懂」，以及举例后紧跟的「这说明」「由此可见」。删掉它；只有带来新事实才留。
3. 假装深刻的说法：真正的问题是、本质上、归根结底、核心在于、A是B的语言、A正在成为陷阱、A不是工具而是镜子。换成具体主张。
4. 铺垫式开场：让我们来看看、接下来聊聊、先说结论、坦白讲、说实话（独立成句的那种）、你需要知道的是。删掉铺垫，直接给内容。
5. 打稻草人：这不是关于A、我并不是说、需要说明的是、别误会、有人可能会说……但。删掉防御句，只留真正的判断。
6. 凑数三连与车轱辘话：三个并列词、三句排比、三段式收尾，只要其中一项没有独立信息就合并或删掉；两句在说同一件事，删后一句。

二、节奏与标点
7. 禁止破折号：不用 —、–，也不用 -- 当连接符。改成逗号、冒号、括号，或直接断句。
8. 打散机械对齐：连续三句以上同长度、同开头（She… She… She…）要合并或换主语；句子要有长有短。
9. 去掉堆叠的模糊限定词（可能、也许、在一定程度上、某种程度上、基本上），除非原文确有不确定。
10. 能用「是 / 有 / 做」就不要用「作为……而存在」「扮演着……的角色」「具有……的特征」。
11. 去掉装饰性加粗与「标签：」式列表；标题不要每个词都大写，不要用符号做装饰。
12. 引号与标点按原文风格统一，中文里不要混用英文弯引号。

三、措辞
13. 高频 AI 词出现即换：实际上、此外、值得注意的是、深入探讨、剖析、赋能、助力、凸显、彰显、多维度、多元化、不可或缺、至关重要、深刻影响、发挥着重要作用、具有里程碑意义、开启了新篇章、格局、画卷。
14. 虚高句删掉：标志着转折点、奠定了坚实基础、产生了深远影响、为……提供了新视角、注入了新活力。只留事实。
15. 借来的权威：专家认为、研究表明、有观点指出。没点名是谁就不写；有具体来源才引用，且不得虚构。
16. 广告腔删掉：令人惊叹、不容错过、坐落于、尽收眼底、无与伦比。
17. 模糊关联：与……相关、与……有联系、涉及。要写清是什么关系；原文没写就别硬补。

四、残留清理（务必删干净）
18. 聊天残留：希望这些对你有帮助、需要我继续吗、当然可以、好问题、下面是……
19. 知识边界声明：截至目前、根据我的了解、公开资料有限、据我所知。
20. 描述文档自身的话：本文说明了、下表对比了、接下来分三部分讲。
21. 标题下面紧跟一句重复标题的话，删掉那句。

五、判断标准
- 每一句留下的都要带来上一句没有的信息，不能只增加重量或情绪。
- 改写后要能读出声，像一个具体的人在跟一个具体的人说话。
- 删掉的是腔调，不是内容；事实、数据、观点一个都不能少，也一个都不能多。

六、硬性红线
- 不得新增原文没有的事实、数据、人名、日期、引文、引用；不得虚构来源。
- 不得改变作者立场与论点。
- 每一处【降AI痕迹】的改动仍按「原句 / 改句 / 说明」列出，说明里写清命中了上面第几条。

【第四步 · 主题深化】
提炼核心论点、补足论证、提升立意层次，但不脱离原主题、不虚构内容。

【第五步 · 流畅度润色】
优化句子节奏、段落衔接、逻辑过渡，保证全文自然流畅。

【第六步 · 三份 A 级版本】
基于以上全部修改，给出三份完整论文版本。先用一句话说明三份各自的侧重（例如：A 版严谨学术、B 版思辨深刻、C 版流畅自然），然后逐版输出，格式固定、不得改动：

### A 版 · 严谨学术
（这一版的正文，段落之间空一行）

【本版字数：1183】

### B 版 · 思辨深刻
（正文）

【本版字数：1201】

### C 版 · 流畅自然
（正文）

【本版字数：1194】

- 每版正文只写论文本身：不要旁注、不要批注、不要「本节说明」「如上所述」这类描述文档自身的话。
- 【本版字数：N】必须单独占一行，不加粗、不放进引用块、不加任何符号。
- N 是你统计的这一版正文字数，不含标题行，也不含这一行本身。
- 三版的行文必须真的不同，不要只改几个词。

【字数纪律】
用户给「目标字数」时，这一节是硬约束，优先级高于本篇其他所有润色要求；没给目标字数就整节忽略。
- 计数口径：中文每字算 1，英文每个单词算 1，数字串算 1。
- 允许误差 ±50 字。用户会把三份版本逐一实测，超出区间就算没完成。
- 三份版本要各自命中，不是三份加起来命中。
- 减字数只能减「腔调与冗余」：论点、证据、数据、引文一个都不能少；也不得为凑字数虚构任何内容。
- 先在内部数一遍再输出，明显超了就重写；不要在正文里解释你是怎么数的。

硬性要求：
- 每处修改都必须「原句 + 改句 + 说明」，不得只给结果。
- 尊重原意，不擅自改变论点，不添加用户没写的内容，不虚构引用与事实。
- 【降AI痕迹】必须逐条对照上面的第 1 到 21 条执行，说明里写清命中哪一条。
- 三份最终版本里不得残留第一组的六类写法，也不得出现任何破折号。
- 三份版本末尾的【本版字数：N】标记必须存在，且 N 与正文实际长度相差不超过 5 字。`;

const INTENSITY_MAP = {
  mild: '轻度：尽量保留原文用词与句式，只做必要的纠错与最小化润色，改动最小。',
  medium: '中度：在保留原意与整体结构的基础上，做适度润色、学术化与优化。',
  strong: '重度：可进行较深度的改写与润色，使表达更学术、更流畅、更有说服力。'
};

function buildUserPrompt(topic, essay, tasks, intensity, opts) {
  const parts = [];
  const o = opts || {};
  if (topic) parts.push('【论文题目】\n' + topic);
  parts.push('【论文正文】\n' + essay);
  if (tasks.length) parts.push('【本次需执行的任务】\n' + tasks.join('、'));
  parts.push('【本次修改力度】\n' + (INTENSITY_MAP[intensity] || INTENSITY_MAP.medium));
  if (o.targetWords > 0) {
    parts.push('【字数要求】\n' + buildWordPlan(o.targetWords, o.strategy, essay, o.prevCounts));
  }
  parts.push('请开始按你的六步流程处理。');
  return parts.join('\n\n');
}

// ============================================================
// 字数：口径必须与前端 preview.html 里的 countWords / countSentences 完全一致
// ============================================================
const WORD_TOLERANCE = 50;

function countWords(text) {
  const s = String(text || '');
  let n = 0;
  const cjk = s.match(/[\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]/g);
  if (cjk) n += cjk.length;
  const lat = s.match(/[A-Za-z]+(?:['’\-][A-Za-z]+)*/g);
  if (lat) n += lat.length;
  const num = s.match(/\d+(?:[.,]\d+)*/g);
  if (num) n += num.length;
  return n;
}

function countSentences(text) {
  const parts = String(text || '').split(/[。！？!?；;…]+|[.!?]+(?=\s|$)|\n+/);
  let n = 0;
  for (let i = 0; i < parts.length; i++) if (parts[i].trim().length >= 3) n++;
  return n;
}

function buildWordPlan(targetWords, strategy, essay, prevCounts) {
  const now = countWords(essay);
  const sentences = countSentences(essay);
  const avg = sentences > 0 ? now / sentences : 0;
  const lo = targetWords - WORD_TOLERANCE;
  const hi = targetWords + WORD_TOLERANCE;
  const lines = [];

  lines.push('目标字数：' + targetWords + ' 字（合格区间 ' + lo + ' – ' + hi + '）');
  lines.push('原文实测：' + now + ' 字 / ' + sentences + ' 句' + (avg ? '，平均每句 ' + avg.toFixed(1) + ' 字' : ''));

  if (targetWords >= now) {
    lines.push('注意：目标不低于原文，这次是扩写而不是压缩，两个「压缩策略」都不适用。');
    lines.push('做法：把已有论点写充分（展开例子、补上解释、把跳跃的推理补成完整链条），不得虚构事实、数据、人名、引文。');
  } else {
    const cut = now - targetWords;
    const pct = Math.round(cut / now * 100);
    lines.push('需要减少：' + cut + ' 字（-' + pct + '%）');

    if (strategy === 'cut') {
      lines.push('达成方式：删改整合（允许删句、并句、重组段落、调整段落顺序）。');
      if (avg > 0) lines.push('换算：按原句平均长度，大约相当于少 ' + Math.round(cut / avg) + ' 句；可以整句删，也可以并句后压。');
      lines.push('优先删：重复论述、空泛总结、为举例而举例的堆砌、与论点无关的铺陈、自问自答的过渡句。');
      lines.push('允许把相邻的两三句合并成一句，也允许拆句；句数可以减少。');
      lines.push('必须保留：全部论点、关键证据、数据、引文、作者立场。');
    } else {
      lines.push('达成方式：保句精简（一句对一句，不得增删句子）。');
      if (sentences > 0) {
        lines.push('换算：句子总数必须仍是 ' + sentences + ' 句，每句平均要从 ' + avg.toFixed(1) + ' 字压到 ' + (targetWords / sentences).toFixed(1) + ' 字。');
      }
      lines.push('压缩来源：冗余修饰、重复表述、可省略的主语与时间状语、把「进行/加以/给予」这类空动词换成实动词、把「具有……的特征」改成直接说。');
      lines.push('某句已经压不动就不要硬压，把削减额度分给更臃肿的句子，但总量必须到位。');
    }
  }

  lines.push('三份版本必须各自命中目标区间，不是三份加起来命中。');
  lines.push('每版正文写完后自己数一遍，超出区间就重写这一版再输出。');

  if (prevCounts && prevCounts.length) {
    const items = prevCounts.map(function (p) {
      const d = p.count - targetWords;
      const sign = d >= 0 ? '+' : '-';
      return '「' + p.title + '」实测 ' + p.count + ' 字（' + sign + Math.abs(d) + '）';
    }).join('；');
    lines.push('上一轮实测：' + items + '。这一轮必须分别落进区间，不要重复上一轮的偏差。');
  }

  return lines.join('\n');
}

// —— 工具函数 ——
function corsHeaders() {
  return {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'POST, GET, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type'
  };
}

function json(obj, status) {
  const headers = corsHeaders();
  headers['Content-Type'] = 'application/json; charset=utf-8';
  return new Response(JSON.stringify(obj), { status: status || 200, headers });
}

// —— 转发后端：调用 DeepSeek（流式） ——
async function handleChat(request, env) {
  try {
    const body = await request.json();
    const topic = String(body.topic || '').trim();
    const essay = String(body.essay || '').trim();
    const tasks = Array.isArray(body.tasks) ? body.tasks : [];
    const intensity = String(body.intensity || 'medium');
    const targetWords = Math.max(0, Math.min(20000, parseInt(body.targetWords || 0, 10) || 0));
    const strategy = String(body.strategy || 'keep') === 'cut' ? 'cut' : 'keep';
    const prevCounts = Array.isArray(body.prevCounts)
      ? body.prevCounts.slice(0, 5).map(function (p) {
          return {
            title: String((p && p.title) || '版本').slice(0, 30),
            count: parseInt((p && p.count) || 0, 10) || 0
          };
        })
      : null;

    if (!essay) return json({ error: '论文正文不能为空' }, 400);
    if (!env.DEEPSEEK_API_KEY) return json({ error: '后端未配置 DEEPSEEK_API_KEY，请参考 README 设置 Secret。' }, 500);

    const upstream = await fetch('https://api.deepseek.com/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + env.DEEPSEEK_API_KEY
      },
      body: JSON.stringify({
        model: 'deepseek-chat',
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          { role: 'user', content: buildUserPrompt(topic, essay, tasks, intensity, { targetWords: targetWords, strategy: strategy, prevCounts: prevCounts }) }
        ],
        stream: true,
        temperature: 0.7,
        max_tokens: 8192
      })
    });

    if (!upstream.ok) {
      const text = await upstream.text();
      return json({ error: 'DeepSeek 接口返回错误（' + upstream.status + '）：' + text }, 502);
    }

    const headers = corsHeaders();
    headers['Content-Type'] = 'text/event-stream; charset=utf-8';
    headers['Cache-Control'] = 'no-cache';
    return new Response(upstream.body, { headers });
  } catch (e) {
    return json({ error: '服务异常：' + (e && e.message ? e.message : String(e)) }, 500);
  }
}

